def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

# Test the function
print(factorial(5))  # Output: 120
print(factorial(0))  # Output: 1

def factorial_iterative(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result
